// i18n message catalogue — 5 languages. Turkish is the reference/default.
// Arabic (ar) is RTL. Listing free-text is authored in TR/EN only; for RU/FR/AR
// UI we show the EN base labelled as machine-translated (real MT is a later job).
export const LOCALES = ["tr", "en", "ru", "fr", "ar"];
export const DEFAULT_LOCALE = "tr";
export const RTL_LOCALES = ["ar"];
export const LOCALE_LABEL = { tr: "TR", en: "EN", ru: "RU", fr: "FR", ar: "AR" };
export const isRTL = (l) => RTL_LOCALES.includes(l);
// which stored listing language to show for a given UI locale
export const listingLang = (l) => (l === "tr" ? "tr" : "en");
export const isMachineTranslated = (l) => !["tr", "en"].includes(l);

